#include <stdio.h>
int main(){
    int burstP1=6, burstP2=4;
    int waitFCFS_P1=0, waitFCFS_P2=burstP1;
    double avgFCFS=(waitFCFS_P1+waitFCFS_P2)/2.0;
    int waitSRTF_P1=burstP2, waitSRTF_P2=0;
    double avgSRTF=(waitSRTF_P1+waitSRTF_P2)/2.0;
    printf("FCFS avg waiting = %.1f ms\n", avgFCFS);
    printf("SRTF avg waiting = %.1f ms\n", avgSRTF);
    return 0;
}
